fn assign_fixed(
    &self,
    layouter: &mut impl Layouter<F>,
    constant: K,
) -> Result<AssignedField<F, K, P>, Error> {
    let base = BI::from(2).pow(P::LOG2_BASE);
    // We shift the value of x by 1, remember that limbs {xi}_i represent integer
    //   1 + sum_i base^i xi
    let constant = (constant - K::ONE).to_biguint().into();
    let constant_limbs = bi_to_limbs(P::NB_LIMBS, &base, &constant);
    let constant_cells = constant_limbs
        .iter()
        .map(|x| self.native_gadget.assign_fixed(layouter, bigint_to_fe::<F>(x)))
        .collect::<Result<Vec<_>, _>>()?;

    // All limbs will be in the range [0, base) by construction, no range-checks are
    // needed.
    // WARNING: We use "loose" bounds (`well_formed_bounds::<F, K, P>()`) here even
    // if we know for certain that the cells contain a constant. This is to
    // avoid a potential completeness issue when calling `assert_equal`.
    // (Using tight bounds could result in an unsatisfiable equal assertion between
    // two equal field elements: one in canonical form and the other one in the
    // non-canonical (but well-formed) form, making the assertion fail when it
    // should not.)

fn add(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
    y: &AssignedField<F, K, P>,
) -> Result<AssignedField<F, K, P>, Error> {
    let zero: AssignedField<F, K, P> = self.assign_fixed(layouter, K::ZERO)?;

    if x == &zero {
        return Ok(y.clone());
    }

    if y == &zero {
        return Ok(x.clone());
    }

    // Note that x := 1 + sum_i base^i xi and y := 1 + sum_i base^i yi.
    // Thus z = (x + y) is equal to 2 + sum_i base^i (xi + yi).
    // Observe there is a 2 instead of the implicit 1, thus we cannot simply add the
    // limbs of x and y pair-wise. We also need to add a factor of +1 to the
    // least-significant limb to account for this difference.

    let mut constants = vec![BI::one()];
    constants.resize(P::NB_LIMBS as usize, BI::zero());

    let z_limb_values = x
        .limb_values
        .iter()
        .zip(y.limb_values.iter())
        .zip(constants.iter().map(|ci| bigint_to_fe::<F>(ci)))
        .map(|((xi, yi), ci)| {
            self.native_gadget.linear_combination(
                layouter,
                &[(F::ONE, xi.clone()), (F::ONE, yi.clone())],
                ci,
            )
        })
        .collect::<Result<Vec<_>, _>>()?;

    let z = AssignedField::<F, K, P> {
        limb_values: z_limb_values,
        limb_bounds: x
            .limb_bounds
            .iter()
            .zip(y.limb_bounds.iter())
            .zip(constants.iter())
            .map(|((xi_bounds, yi_bounds), ci)| {
                (
                    &xi_bounds.0 + &yi_bounds.0 + ci,
                    &xi_bounds.1 + &yi_bounds.1 + ci,
                )
            })
            .collect(),
        _marker: PhantomData,
    };
    self.normalize_if_approaching_limit(layouter, &z)
}

fn sub(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
    y: &AssignedField<F, K, P>,
) -> Result<AssignedField<F, K, P>, Error> {
    let zero: AssignedField<F, K, P> = self.assign_fixed(layouter, K::ZERO)?;

    if y == &zero {
        return Ok(x.clone());
    }

    // Note that x := 1 + sum_i base^i xi and y := 1 + sum_i base^i yi.
    // Thus z = (x - y) is equal to 0 + sum_i base^i (xi + yi).
    // Observe there is a 0 instead of the implicit 1, thus we cannot simply
    // subtract the limbs of x and y pair-wise. We also need to add a factor
    // of -1 to the least-significant limb to account for this difference.

    let mut constants = vec![BI::from(-1)];
    constants.resize(P::NB_LIMBS as usize, BI::zero());

    let z_limb_values = x
        .limb_values
        .iter()
        .zip(y.limb_values.iter())
        .zip(constants.iter().map(|ci| bigint_to_fe::<F>(ci)))
        .map(|((xi, yi), ci)| {
            self.native_gadget.linear_combination(
                layouter,
                &[(F::ONE, xi.clone()), (-F::ONE, yi.clone())],
                ci,
            )
        })
        .collect::<Result<Vec<_>, _>>()?;

    let z = AssignedField::<F, K, P> {
        limb_values: z_limb_values,
        limb_bounds: x
            .limb_bounds
            .iter()
            .zip(y.limb_bounds.iter())
            .zip(constants.iter())
            .map(|((xi_bounds, yi_bounds), ci)| {
                (
                    &xi_bounds.0 - &yi_bounds.1 + ci,
                    &xi_bounds.1 - &yi_bounds.0 + ci,
                )
            })
            .collect(),
        _marker: PhantomData,
    };
    self.normalize_if_approaching_limit(layouter, &z)
}

fn mul(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
    y: &AssignedField<F, K, P>,
    multiplying_constant: Option<K>,
) -> Result<AssignedField<F, K, P>, Error> {
    let zero: AssignedField<F, K, P> = self.assign_fixed(layouter, K::ZERO)?;
    let one: AssignedField<F, K, P> = self.assign_fixed(layouter, K::ONE)?;

    if x == &zero || y == &zero {
        return Ok(zero);
    }

    if x == &one {
        return Ok(y.clone());
    }

    if y == &one {
        return Ok(x.clone());
    }

    let y = match multiplying_constant {
        None => y.clone(),
        Some(k) => self.mul_by_constant(layouter, y, k)?,
    };
    self.assign_mul(layouter, x, &y, false)
}

fn div(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
    y: &AssignedField<F, K, P>,
) -> Result<AssignedField<F, K, P>, Error> {
    let one: AssignedField<F, K, P> = self.assign_fixed(layouter, K::ONE)?;
    if y == &one {
        return Ok(x.clone());
    }

    let y = self.normalize(layouter, y)?;
    self.assert_non_zero(layouter, &y)?;
    self.assign_mul(layouter, x, &y, true)

fn assign_mul(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
    y: &AssignedField<F, K, P>,
    division: bool,
) -> Result<AssignedField<F, K, P>, Error> {
    let base = BI::from(2).pow(P::LOG2_BASE);
    let nb_limbs = P::NB_LIMBS;

    let x = self.normalize(layouter, x)?;
    let y = self.normalize(layouter, y)?;

    y.value().error_if_known_and(|yv| division && K::is_zero(yv).into())?;

    let zv = x
        .value()
        .zip(y.value())
        .map(|(xv, yv)| {
            if division {
                xv * yv.invert().unwrap()
            } else {
                xv * yv
            }
        })
        .map(|z| bi_to_limbs(nb_limbs, &base, &(z - K::ONE).to_biguint().into()));
    let z_values = (0..nb_limbs)
        .map(|i| zv.clone().map(|zs| bigint_to_fe::<F>(&zs[i as usize])))
        .collect::<Vec<_>>();

    // Assign and range-check the z limbs
    let z_limbs = z_values
        .iter()
        .zip(well_formed_log2_bounds::<F, K, P>().iter())
        .map(|(&z_value, &log2_bound)| {
            self.native_gadget.assign_lower_than_fixed(
                layouter,
                z_value,
                &(BigUint::one() << log2_bound),
            )
        })
        .collect::<Result<Vec<_>, Error>>()?;

    let z = AssignedField::<F, K, P> {
        limb_values: z_limbs,
        limb_bounds: well_formed_bounds::<F, K, P>(),
        _marker: PhantomData,
    };

    // Divisions z = x / y are modeled as multiplications z * y = x.
    // We swap x and z when division = true.
    let (l, r) = if !division { (&x, &z) } else { (&z, &x) };
    mul::assert_mul::<F, K, P, N>(
        layouter,
        l,
        &y,
        r,
        &self.config.mul_config,
        &self.native_gadget,
    )?;

    Ok(z)

/// Normalizes the given assigned field element, but only if its bounds
/// exceed the limits of the well-formed bounds.
pub(crate) fn normalize(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
) -> Result<AssignedField<F, K, P>, Error> {
    if x.is_well_formed() {
        Ok(x.clone())
    } else {
        self.make_canonical(layouter, x)
    }
}

/// Normalizes the given assigned field element, but only if its bounds
/// are approaching the limits of the well-formed bounds.
pub(crate) fn normalize_if_approaching_limit(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
) -> Result<AssignedField<F, K, P>, Error> {
    // This threshold was chosen empirically.
    let threshold: BI = P::max_limb_bound() / 10;
    let dangerous_lower_bounds = x.limb_bounds.iter().any(|b| b.0 < -threshold.clone());
    let dangerous_upper_bounds = x.limb_bounds.iter().any(|b| b.1 > threshold);
    if dangerous_lower_bounds || dangerous_upper_bounds {
        self.make_canonical(layouter, x)
    } else {
        Ok(x.clone())
    }
}

/// Converts the given assigned field element into an equivalent one
/// represented in canonical form, through the normalization procedure.
fn make_canonical(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
) -> Result<AssignedField<F, K, P>, Error> {
    let max_limb_bound = P::max_limb_bound();
    x.limb_bounds.iter().for_each(|(lower, upper)| {
        if lower < &(-&max_limb_bound) || upper > &max_limb_bound {
            panic!(
                "make_canonical: the limb bounds of the input: [{}, {}] exceed the
                 maximum limb bound value {}; consider applying a normalization
                 earlier, when the bounds are still within the permited range;
                 increasing the [max_limb_bound] of your FieldEmulationParams could also
                 help, if possible.",
                lower, upper, max_limb_bound
            );
        }
    });
    let z_limbs = norm::normalize::<F, K, P, N>(
        layouter,
        x,
        &self.config.norm_config,
        &self.native_gadget,
    )?;
    let z = AssignedField::<F, K, P> {
        limb_values: z_limbs,
        limb_bounds: well_formed_bounds::<F, K, P>(),
        _marker: PhantomData,
    };

fn configure_from_scratch(
    meta: &mut ConstraintSystem<F>,
    advice_columns: &mut Vec<Column<Advice>>,
    fixed_columns: &mut Vec<Column<Fixed>>,
    instance_columns: &[Column<Instance>; 2],
) -> FieldChipConfigForTests<F, N> {
    let native_gadget_config = <N as FromScratch<F>>::configure_from_scratch(
        meta,
        advice_columns,
        fixed_columns,
        instance_columns,
    );
    // Use hard-coded pow2range values matching NativeGadget::configure_from_scratch
    let nb_parallel_range_checks = 4;
    let max_bit_len = 8;
    let field_chip_config = {
        let nb_fc_cols = nb_field_chip_columns::<F, K, P>();
        while advice_columns.len() < nb_fc_cols {
            advice_columns.push(meta.advice_column());
        }
        FieldChip::<F, K, P, N>::configure(
            meta,
            &advice_columns[..nb_fc_cols],
            nb_parallel_range_checks,
            max_bit_len,
        )
    };

pub fn bounds<F, K, P>(
    nb_parallel_range_checks: usize,
    max_bit_len: u32,
) -> ((BI, BI), Vec<(BI, BI)>)
where
    F: CircuitField,
    K: CircuitField,
    P: FieldEmulationParams<F, K>,
{
    let base = BI::from(2).pow(P::LOG2_BASE);
    let nb_limbs = P::NB_LIMBS;
    let moduli = P::moduli();
    let base_powers = P::base_powers();
    let double_base_powers = P::double_base_powers();

    // Note that x := 1 + sum_i base^i x_i, and that y, z are defined analogously.
    //
    // We enforce z - x * y = 0 (mod m) with the equation:
    //  sum_xy + sum_x + sum_y - sum_z = k * m
    //
    // where
    //  sum_xy := sum_i (sum_j (base^{i+j} % m) * x_i * y_j),
    //   sum_x := sum_i (base^i % m) * x_i ,
    //   sum_y := sum_i (base^i % m) * y_i ,
    //   sum_z := sum_i (base^i % m) * z_i .

    let limbs_max = vec![&base - BI::one(); nb_limbs as usize];
    let limbs_max2 = vec![(&base - BI::one()).pow(2); (nb_limbs * nb_limbs) as usize];
    let max_sum_xy = sum_bigints(&double_base_powers, &limbs_max2);
    let max_sum_z = sum_bigints(&base_powers, &limbs_max);
    let max_sum_x = max_sum_z.clone();
    let max_sum_y = max_sum_z.clone();
    let expr_min = -max_sum_z;
    let expr_max = &max_sum_xy + &max_sum_x + &max_sum_y;
    let expr_bounds = (expr_min, expr_max);

    let expr_mj_bounds: Vec<_> = moduli
        .iter()
        .map(|mj| {
            let base_powers_mj = base_powers.iter().map(|b| b.rem(mj)).collect::<Vec<_>>();
            let double_base_powers_mj =
                double_base_powers.iter().map(|b| b.rem(mj)).collect::<Vec<_>>();
            let max_sum_xy_mj = sum_bigints(&double_base_powers_mj, &limbs_max2);
            let max_sum_z_mj = sum_bigints(&base_powers_mj, &limbs_max);
            let max_sum_x_mj = max_sum_z_mj.clone();
            let max_sum_y_mj = max_sum_z_mj.clone();
            let expr_mj_min = -max_sum_z_mj;
            let expr_mj_max = &max_sum_xy_mj + &max_sum_x_mj + &max_sum_y_mj;
            (expr_mj_min, expr_mj_max)
        })
        .collect();
    get_identity_auxiliary_bounds::<F, K>(
        "mul",
        &moduli,
        expr_bounds,
        &expr_mj_bounds,
        nb_parallel_range_checks,
        max_bit_len,
    )

pub fn assert_mul<F, K, P, RangeGadget>(
    layouter: &mut impl Layouter<F>,
    x: &AssignedField<F, K, P>,
    y: &AssignedField<F, K, P>,
    z: &AssignedField<F, K, P>,
    mul_config: &MulConfig,
    range_gadget: &RangeGadget,
) -> Result<(), Error>
where
    F: CircuitField,
    K: CircuitField,
    P: FieldEmulationParams<F, K>,
    RangeGadget: RangeCheckInstructions<F, AssignedNative<F>>,
{
    let mut range_checks = layouter.assign_region(
        || "Foreign multiplication",
        |mut region| {
            let mut offset = 0;

            let m = &K::modulus().to_bigint().unwrap();

        mul_config.q_mul.enable(&mut region, offset)?;

        x.limb_values()
            .iter()
            .zip(mul_config.xy_cols.iter())
            .map(|(cell, &col)| cell.copy_advice(|| "assert_mul x", &mut region, col, offset))
            .collect::<Result<Vec<_>, _>>()?;

        z.limb_values()
            .iter()
            .zip(mul_config.z_cols.iter())
            .map(|(cell, &col)| cell.copy_advice(|| "assert_mul z", &mut region, col, offset))
            .collect::<Result<Vec<_>, _>>()?;

        offset += 1;

        y.limb_values()
            .iter()
            .zip(mul_config.xy_cols.iter())
            .map(|(cell, &col)| cell.copy_advice(|| "assert_mul y", &mut region, col, offset))
            .collect::<Result<Vec<_>, _>>()?;

        let u_value = u.clone().map(|u| bigint_to_fe::<F>(&u));
        let u_cell = region.assign_advice(
            || "assert_mul u",
            mul_config.z_cols[0],
            offset,
            || u_value,
        )?;

        let vs_cells = vs_values
            .zip(mul_config.z_cols[1..=mul_config.vs_bounds.len()].iter())
            .map(|(vj, &vj_col)| {
                let vj_value = vj.map(|vj| bigint_to_fe::<F>(&vj));
                region.assign_advice(|| "assert_mul vj", vj_col, offset, || vj_value)
            })
            .collect::<Result<Vec<_>, _>>()?;

        // u_cell will be range-checked in [0, u_max)
        let u_range_check = (u_cell, u_max);

        // Every vj_cell will be range-checked in [0, vj_max)
        let vs_max = mul_config.vs_bounds.clone().into_iter().map(|(_, vj_max)| vj_max.clone());
        let vs_range_checks =
            vs_cells.into_iter().zip(vs_max.collect::<Vec<_>>()).collect::<Vec<_>>();

        // Assert all range-checks
        Ok([u_range_check].into_iter().chain(vs_range_checks.into_iter()))
    },
)?;
range_checks.try_for_each(|(cell, ubound)| {
    range_gadget.assert_lower_than_fixed(layouter, &cell, ubound.magnitude())
})

pub fn bounds<F, K, P>(
    nb_parallel_range_checks: usize,
    max_bit_len: u32,
) -> ((BI, BI), Vec<(BI, BI)>)
where
    F: CircuitField,
    K: CircuitField,
    P: FieldEmulationParams<F, K>,
{
    let base = BI::from(2).pow(P::LOG2_BASE);
    let nb_limbs = P::NB_LIMBS;
    let moduli = P::moduli();
    let max_limb_bound = P::max_limb_bound();
    let base_powers = P::base_powers();

    // Let x be the possibly non-well-formed emulated field element to be normalized
    // and let z be its normal form.
    //
    // Note that x := 1 + sum_i base^i x_i, and that z is defined analogously.
    //
    // The limbs of x are guaranteed to be within the range [-max_limb_bound,
    // max_limb_bound]. On the other hand, the limbs of z will be asserted to be
    // in the range [0, base). We enforce x - z = 0 (mod m) with equation:
    //  sum_shifted_x - sum_z - sum_shifts = k * m
    //
    // where
    //   sum_shifted_x := sum_i base_power_i * (x_i + max_limb_bound) .
    //           sum_z := sum_i base_power_i * z_i .
    //      sum_shifts := sum_i base_power_i * max_limb_bound
    //
    // The shifts of max_limb_bound are introduced to correct any wrap-arounds over
    // the native modulus due to negative vaues of x_i.
    // Note that (x_i + max_limb_bound) is guaranteed to be in the range
    // [0, 2 * max_limb_bound].

    let shifts = vec![max_limb_bound; nb_limbs as usize];
    let sum_shifts = sum_bigints(&base_powers, &shifts);
    let max_sum_shifted_x = &sum_shifts + &sum_shifts;
    let z_limbs_max = vec![&base - BI::one(); nb_limbs as usize];
    let max_sum_z = sum_bigints(&base_powers, &z_limbs_max);
    let expr_min = -&max_sum_z - &sum_shifts;
    let expr_max = &max_sum_shifted_x - &sum_shifts;
    let expr_bounds = (expr_min, expr_max);

    let expr_mj_bounds: Vec<_> = moduli
        .iter()
        .map(|mj| {
            let base_powers_mj = base_powers.iter().map(|b| b.rem(mj)).collect::<Vec<_>>();
            let sum_shifts_mj = sum_bigints(&base_powers_mj, &shifts);
            let max_sum_shifted_x_mj = &sum_shifts_mj + &sum_shifts_mj;
            let max_sum_z_mj = sum_bigints(&base_powers_mj, &z_limbs_max);
            let expr_mj_min = -&max_sum_z_mj - urem(&sum_shifts, mj);
            let expr_mj_max = &max_sum_shifted_x_mj - urem(&sum_shifts, mj);
            (expr_mj_min, expr_mj_max)
        })
        .collect();
    get_identity_auxiliary_bounds::<F, K>(
        "normalization",
        &moduli,
        expr_bounds,
        &expr_mj_bounds,
        nb_parallel_range_checks,
        max_bit_len,
    )

let q_norm = meta.selector();

// The layout is in two rows:
// | x0 ... xk | z0 ... zk   |  <- selector enabled here
// |           | u v0 ... vl |

        norm_config.q_norm.enable(&mut region, offset)?;

        let x_limb_values = x.limb_values();
        let x_iter = x_limb_values.iter().zip(norm_config.x_cols.iter());
        x_iter
            .map(|(cell, &col)| cell.copy_advice(|| "norm input", &mut region, col, offset))
            .collect::<Result<Vec<_>, _>>()?;

        let z_cells = z_values
            .zip(norm_config.z_cols.iter())
            .map(|(z, &z_col)| region.assign_advice(|| "norm output", z_col, offset, || z))
            .collect::<Result<Vec<_>, _>>()?;

        offset += 1;

        let u_value = u.clone().map(|u| bigint_to_fe::<F>(&u));
        let u_cell =
            region.assign_advice(|| "norm u", norm_config.z_cols[0], offset, || u_value)?;

        let vs_cells = vs_values
            .iter()
            .zip(norm_config.z_cols[1..=norm_config.vs_bounds.len()].iter())
            .map(|(vj, &vj_col)| {
                let vj_value = vj.clone().map(|vj| bigint_to_fe::<F>(&vj));
                region.assign_advice(|| "norm vj", vj_col, offset, || vj_value)
            })
            .collect::<Result<Vec<_>, _>>()?;

        // Every z_cell will be range-checked in [0, base)
        let z_range_checks = z_cells
            .clone()
            .into_iter()
            .zip(well_formed_log2_bounds::<F, K, P>().iter())
            .map(|(cell, log2_bound)| (cell, BI::from(2).pow(*log2_bound)))
            .collect::<Vec<_>>();

        // u_cell will be range-checked in [0, u_max)
        let u_range_check = (u_cell, u_max);

        // Every vj_cell will be range-checked in [0, vj_max)
        let vs_max =
            norm_config.vs_bounds.clone().into_iter().map(|(_, vj_max)| vj_max.clone());
        let vs_range_checks =
            vs_cells.into_iter().zip(vs_max.collect::<Vec<_>>()).collect::<Vec<_>>();

        // Assert all range-checks
        Ok((
            z_range_checks
                .into_iter()
                .chain([u_range_check].into_iter())
                .chain(vs_range_checks.into_iter()),
            z_cells,
        ))
    },
)?;

range_checks.try_for_each(|(cell, ubound)| {
    range_gadget.assert_lower_than_fixed(layouter, &cell, ubound.magnitude())
})?;

Ok(z_cells)

/// Computes the logarithm in base 2 of the given value, rounded up.
pub fn ceil_log2(value: &BI) -> u32 {
    BI::bits(&(value - BI::one())) as u32
}

/// Like `next_power_of_two`, but picks the power of 2 that minimizes
/// range-check cost. A larger power of 2 might be cheaper to range-check
/// if its bit count aligns better with the decomposition chip's parallel
/// lookup structure (all lookups in a row must use the same bit-length tag).
fn next_cheapest_power_of_two(nb_parallel_range_checks: usize, max_bit_len: u32, x: &BI) -> BI {
    let mut solutions = std::collections::HashMap::new();
    let cost = |solutions: &mut std::collections::HashMap<i32, Vec<Vec<usize>>>, bound: u32| {
        compute_optimal_limb_sizes(
            solutions,
            nb_parallel_range_checks,
            max_bit_len as usize,
            bound as i32,
        )
        .len()
    };

    let base_log = ceil_log2(x);
    let mut best_log = base_log;
    let mut best_cost = cost(&mut solutions, base_log);

    // Search for a larger power of 2 that is cheaper to range-check.
    // Looking amongst the next 128 powers is more than enough.
    for i in 1..=128 {
        let c = cost(&mut solutions, base_log + i);
        if c < best_cost {
            best_cost = c;
            best_log = base_log + i;
        }
    }
    BI::pow(&BI::from(2), best_log)
}

pub fn get_identity_auxiliary_bounds<F, K>(
    equation_name: &str,
    moduli: &[BI],
    expr_bounds: (BI, BI),
    expr_mj_bounds: &[(BI, BI)],
    nb_parallel_range_checks: usize,
    max_bit_len: u32,
) -> ((BI, BI), Vec<(BI, BI)>)
where
    F: CircuitField,
    K: CircuitField,
{
    let m = &K::modulus().to_bigint().unwrap();
    let native_modulus = &F::modulus().to_bigint().unwrap();
    // We enforce expr = 0 (mod m) with the equation expr = k * m
    //
    // expr_bounds := (expr_min, expr_max) contain lower and upper bounds
    // respectively on the value that expr can take. We can use them to bound the
    // value of k.
    let k_min = expr_bounds.0.div_ceil(m);
    let k_max = expr_bounds.1.div_floor(m);

    // By defining u := k - k_min, we can express the above equation as:
    //  expr = (u + k_min) * m
    //
    // The advantage of this is that now u is restricted in the range [0, u_max),
    // (for any u_max > k_max - k_min), a constraint that can be enforced through
    // range-checks.
    let u_max = next_cheapest_power_of_two(
        nb_parallel_range_checks,
        max_bit_len,
        &(&k_max - &k_min + BI::one()),
    );

    // Now, assuming u is restricted in [0, u_max), we will bound the amount:
    //  expr - (u + k_min) * m
    //
    //  lower_bound:  expr_bounds.0 - (u_max + k_min) * m
    //  upper_bound:  expr_bounds.1 - k_min * m

    // If we define M := {native_modulus, moduli}, and lcm(M) > |lower_bound|,
    // lcm(M) > upper_bound, then a solution modulo lcm(M) implies a solution over
    // the integers.
    let lower_bound = expr_bounds.0 - (&u_max + &k_min) * m;
    let upper_bound = expr_bounds.1 - &k_min * m;

    // We take moduli until the lcm threshold is is exceeded
    let mut necessary_moduli = vec![];
    let mut lcm = native_modulus.clone();
    for mj in moduli.iter() {
        if lcm > -&lower_bound && lcm > upper_bound {
            break;
        }
        lcm = lcm.lcm(mj);
        necessary_moduli.push(mj.clone());
    }
    if lcm <= -lower_bound || lcm <= upper_bound {
        panic!("lcm-threshold not reached, consider using extra auxiliari moduli")
    }

    // In order to enforce the above equation modulo lcm(M), we need to enforce
    // the following equation for every mj in M:
    //  expr_mj - u * (m % mj) - (k_min * m) % mj = lj * mj ,
    //
    // with the exception of the native modulus, p, for which we can directly check:
    //  expr - (u + k_min) * m =_p 0 .
    //
    // Here, expr_mj is an expression equivalent to expr (mod mj), obtained by
    // possibly having reduced the coefficients of expr modulo mj.
    // The slice expr_mj_bounds contain lower and upper bound pairs on the values of
    // expr_mj, for every mj.
    //
    // We can bound the value of every auxiliary variable lj as:
    //  lj_min := (expr_mj_min - u_max * (m % mj) - (k_min * m) % mj ) / mj
    //  lj_max := (expr_mj_max - (k_min * m) % mj ) / mj
    //
    // Note that k_min is negative, so we must consider it when computing lj_max.
    // On the other hand, we do not have to consider it when computing lj_min, but
    // we choose to do it because it leads to a better ("less negative") bound.
    let v_bounds: Vec<_> = necessary_moduli
        .iter()
        .zip(expr_mj_bounds.iter())
        .map(|(mj, (expr_mj_min, expr_mj_max))| {
            let k_min_m_mod_mj = urem(&(&k_min * m), mj);
            let lj_min = (expr_mj_min - &u_max * urem(m, mj) - &k_min_m_mod_mj).div_ceil(mj);
            let lj_max = (expr_mj_max - &k_min_m_mod_mj).div_floor(mj);

            // As before, by defining vj := lj - lj_min, we can express the equation as:
            //  expr_mj - u * (m % mj) - (k_min * m) % mj = (vj + lj_min) * mj
            //
            // Now, vj can be restricted in the range [0, vj_max),
            // (for any vj_max > lj_max - lj_min).
            let vj_max = next_cheapest_power_of_two(
                nb_parallel_range_checks,
                max_bit_len,
                &(&lj_max - &lj_min + BI::one()),
            );

            // Now, assuming vj is restricted in [0, vj_max), we will bound the amount:
            //  expr_mj - u * (m % mj) - (k_min * m) % mj - (vj + lj_min) * mj

            let lower_bound =
                expr_mj_min - &u_max * urem(m, mj) - &k_min_m_mod_mj - (&vj_max + &lj_min) * mj;

            let upper_bound = expr_mj_max - &k_min_m_mod_mj - &lj_min * mj;

            // Assert that there will be no wrap-around when checking the equality mod mj.
            if *native_modulus <= -lower_bound || *native_modulus <= upper_bound {
                panic!(
                    "Equation {} modulo {} may wrap-around the native modulus",
                    equation_name, mj
                )
            }
            (lj_min, vj_max)
        })
        .collect();
    ((k_min, u_max), v_bounds)

pub(crate) fn compute_optimal_limb_sizes(
    solutions: &mut HashMap<i32, Vec<Vec<usize>>>,
    max_parallel_lookups: usize,
    max_bit_length: usize,
    // we use an i32 type because of the operation `bound - (bit_length * parallel_lookups)`
    // which could result in a negative number (although such cases are filtered)
    bound: i32,
) -> Vec<Vec<usize>> {
    // solution already computed
    #[allow(clippy::map_entry)]
    if solutions.contains_key(&bound) {
        solutions.get(&bound).unwrap().to_vec()
    }
    // trivial bound
    else if bound == 0 {
        solutions.insert(bound, vec![]);
        vec![]
    } else {
        let (mut opt_solution, mut opt_value) = (Vec::new(), usize::MAX);
        // iterate over all possibile pairs
        for parallel_lookups in 1..=max_parallel_lookups {
            for bit_length in (1..=max_bit_length).rev() {
                let next_bound = bound - (bit_length * parallel_lookups) as i32;
                if next_bound >= 0 {
                    // compute the optimal solution of the next problem
                    let mut sol = compute_optimal_limb_sizes(
                        solutions,
                        max_parallel_lookups,
                        max_bit_length,
                        next_bound,
                    );
                    // add one vector for what is left
                    sol.push(vec![bit_length; parallel_lookups]);
                    // if the solution is shorter than the current best, update the optimial
                    // solution and its value
                    if sol.len() < opt_value {
                        opt_value = sol.len();
                        opt_solution = sol;
                    }
                }
            }
        }
        solutions.insert(bound, opt_solution.clone());
        opt_solution
    }
}

layouter.assign_region(
    || "decompose core",
    |mut region| {
        let mut offset = 0;

        // compute the range_check tags for each column
        let tags = limb_sizes.chunks(nr_pow2range_cols).map(|x| x[0]).collect::<Vec<_>>();

        // compute the linear combination terms, i.e. (coef, limb) pairs
        // by convention the coefficient of a zero sized limb is 0 so no constraint
        // needs to be imposed in the corresponding limb
        let coefficients = variable_limbsize_coefficients::<F>(limb_sizes);
        let limbs = x
            .map(|x_value| decompose_in_variable_limbsizes(&x_value, limb_sizes))
            .transpose_vec(limb_sizes.len());

        // we create the terms for the linear combination.
        let terms = coefficients.into_iter().zip(limbs.iter().copied()).collect::<Vec<_>>();

        // assign terms for linear combination
        let native_chip = self.native_chip();
        let (assigned_limbs, assigned_result) = native_chip.assign_linear_combination_aux(
            &mut region,
            terms.as_slice(),
            F::ZERO,
            &x,
            nr_pow2range_cols,
            &mut offset,
        )?;
        offset += 1;

        // enable the appropriate copy constraints in the rows where we assigned the
        // linear combination terms
        let pow2range_chip = self.pow2range_chip();

        // we reverse since we do the range-checks from higher end to start
        for (i, tag) in tags.into_iter().rev().enumerate() {
            let current_row = offset - (i + 1);
            pow2range_chip.assert_row_lower_than_2_pow_n(&mut region, tag, current_row)?;
        }

        // we remove the trivial coefficients, i.e. those corresponding to a zero size
        // limb, and return
        let limbs = assigned_limbs
            .into_iter()
            .zip(limb_sizes.iter())
            .filter(|(_assigned_limb, limb_size)| !limb_size.is_zero())
            .map(|(assigned_limb, _)| assigned_limb)
            .collect::<Vec<_>>();
        Ok((assigned_result, limbs))
    },
)

fn assign_less_than_pow2(
    &self,
    layouter: &mut impl Layouter<F>,
    value: Value<F>,
    bit_length: usize,
) -> Result<AssignedNative<F>, Error> {
    #[cfg(not(test))]
    assert!((bit_length as u32) < F::NUM_BITS);

    // 1. get the limb sizes that minimize the number of parallel lookup rangechecks
    // should never panic since the HashMap contains all possible solutions
    let mut optimal_limb_sizes = self.opt_limbs.get(&(bit_length as i32)).unwrap().clone();

    // 2. process them by adding 0 terms in non-full rows
    optimal_limb_sizes
        .iter_mut()
        .for_each(|row| process_limb_sizes(self.pow2range_chip.config().val_cols.len(), row));
    let limb_sizes = optimal_limb_sizes.concat();

    // 3. use decompose_core to compute the result
    let (y, _) = self.decompose_core(layouter, value, &limb_sizes)?;

    Ok(y)

/// Function that guarantees that x < 2^{bit_length}
fn assert_less_than_pow2(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedNative<F>,
    bit_length: usize,
) -> Result<(), Error> {
    let y = self.assign_less_than_pow2(layouter, x.value().copied(), bit_length)?;
    layouter.assign_region(
        || "copy",
        |mut region| region.constrain_equal(x.cell(), y.cell()),
    )
}

pub const NB_ARITH_COLS: usize = 5;

/// Number of fixed columns used by the identity of the native chip.
pub const NB_ARITH_FIXED_COLS: usize = NB_ARITH_COLS + 4;

/// Number of additions (by constant) that can be performed in
/// parallel in 1 row. This number should not exceed [NB_ARITH_COLS].
///
/// The Poseidon chip requires this number to match the Poseidon
/// register width. Have that into consideration before modifying
/// this number.
const NB_PARALLEL_ADD_COLS: usize = 3;

/// Config defines fixed and witness columns of the main gate
#[derive(Clone, Debug)]
pub struct NativeConfig {
    q_arith: Selector,
    q_12_minus_34: Selector,
    q_par_add: Selector,
    pub(crate) value_cols: [Column<Advice>; NB_ARITH_COLS],
    coeff_cols: [Column<Fixed>; NB_ARITH_COLS],
    q_next_col: Column<Fixed>,
    mul_ab_col: Column<Fixed>,
    mul_ac_col: Column<Fixed>,
    constant_col: Column<Fixed>,
    fixed_values_col: Column<Fixed>,
    committed_instance_col: Column<Instance>,

assert!(cols_used < NB_ARITH_COLS);

// If |terms| <= cols_used, we assert the relation in one row.
// Otherwise we consume up to `cols_used` terms to reduce to a linear
// combination of smaller size.
let chunk_len = min(terms.len(), cols_used);

// Initialize the coefficients vector
let mut coeffs = [F::ZERO; NB_ARITH_COLS];

// assign the lc result in the first advice column
let assigned_result = region.assign_advice(
    || "assign linear combination term",
    self.config.value_cols[0],
    *offset,
    || *result,
)?;
coeffs[0] = -F::ONE;

// assign the first `chunk_len` terms values in the current row
let mut assigned_limbs = terms[0..chunk_len]
    .iter()
    .enumerate()
    .map(|(i, term)| {
        coeffs[i + 1] = term.0;
        region.assign_advice(
            || "assign linear combination term",
            self.config.value_cols[i + 1],
            *offset,
            || term.1,
        )
    })
    .collect::<Result<Vec<_>, _>>()?;

// If everything fits in this row, we add the constraint in the current row and
// finish.
if terms.len() <= cols_used {
    self.custom(
        region,
        &coeffs,
        F::ZERO,
        (F::ZERO, F::ZERO),
        constant,
        *offset,
    )?;
    Ok((assigned_limbs, assigned_result))
}
// Otherwise, we recurse on the remaining terms with the new result.
else {
    // compute the next result: `result - \sum c_j a_j` for j in the chunk
    let chunk_result =
        terms[..chunk_len].iter().fold(Value::known(constant), |acc, (coeff, x)| {
            acc.zip(*x).map(|(acc, val)| acc + *coeff * val)
        });
    let next_result = *result - chunk_result;

    // the cells will be after the next recursive call of the following form
    // offset:      (-1, result)       | (c_1, a_1) | (c_2, a_2) | ... | (c_j, a_j)
    // offset+1:    (-1, new_result)   |    ...     |    ...     | ... |    ...
    //
    // We need to verify the constraint `result - sum c_j a_j = new_result`,
    // equivalently `new_result - result + sum c_j a_j = 0`.
    //
    // We add the terms in the current row (i.e. `sum c_j a_j - result`)
    // and use the selector q_next_coeff to also add the first advice cell of the
    // next column
    self.custom(
        region,
        &coeffs,
        F::ONE,
        (F::ZERO, F::ZERO),
        constant,
        *offset,
    )?;
    *offset += 1;
    let (new_assigned_limbs, _) = self.assign_linear_combination_aux(
        region,
        &terms[chunk_len..],
        F::ZERO,
        &next_result,
        cols_used,
        offset,
    )?;
    assigned_limbs.extend_from_slice(&new_assigned_limbs);
    Ok((assigned_limbs, assigned_result))
}

fn assign_fixed(
    &self,
    layouter: &mut impl Layouter<F>,
    constant: F,
) -> Result<AssignedNative<F>, Error> {
    let constant_big = constant.to_biguint();
    if let Some(assigned) = self.cached_fixed.borrow().get(&constant_big) {
        return Ok(assigned.clone());
    };

    let x = layouter.assign_region(
        || "Assign fixed",
        |mut region| {
            let mut x = region.assign_fixed(
                || "fixed",
                self.config.fixed_values_col,
                0,
                || Value::known(constant),
            )?;
            // This is hacky but necessary because we are treating a fixed cell as an
            // assigned one. Fixed cells do not get properly filled until the end.
            x.update_value(constant)?;
            Ok(x)
        },
    )?;

    // Save the assigned constant in the cache.
    self.cached_fixed.borrow_mut().insert(constant_big.clone(), x.clone());

    Ok(x)

fn linear_combination(
    &self,
    layouter: &mut impl Layouter<F>,
    terms: &[(F, AssignedNative<F>)],
    constant: F,
) -> Result<AssignedNative<F>, Error> {
    let zero: AssignedNative<F> = self.assign_fixed(layouter, F::ZERO)?;

    let terms: Vec<_> = terms
        .iter()
        .filter(|(c, x)| !F::is_zero_vartime(c) && *x != zero)
        .cloned()
        .collect();

    if terms.is_empty() {
        return self.assign_fixed(layouter, constant);
    }

    // If only one term remains after filtering, we may early return.
    if let [(coeff, var)] = terms.as_slice() {
        if *coeff == F::ONE && F::is_zero_vartime(&constant) {
            return Ok(var.clone());
        }
    }

    // Maybe a  &[(F, AssignedNative<F>)] (and correspondingly to the aux function.
    // Do we really need slices with references?
    let term_values = terms
        .iter()
        .map(|(c, assigned_t)| (*c, assigned_t.value().copied()))
        .collect::<Vec<_>>();

    let result = terms.iter().fold(Value::known(constant), |acc, (coeff, x)| {
        acc.zip(x.value()).map(|(acc, val)| acc + *coeff * val)
    });

    layouter.assign_region(
        || "Linear combination",
        |mut region| {
            let mut offset = 0;
            let (assigned_limbs, assigned_result) = self.assign_linear_combination_aux(
                &mut region,
                term_values.as_slice(),
                constant,
                &result,
                NB_ARITH_COLS - 1,
                &mut offset,
            )?;

            assert_eq!(assigned_limbs.len(), terms.len());

            // assert the newly assigned values are equal to the one given as input
            assigned_limbs.iter().zip(terms.iter()).try_for_each(|(new_av, (_, av))| {
                region.constrain_equal(new_av.cell(), av.cell())
            })?;

            Ok(assigned_result)
        },
    )
}

fn assign_lower_than_fixed(
    &self,
    layouter: &mut impl Layouter<F>,
    value: Value<F>,
    bound: &BigUint,
) -> Result<AssignedNative<F>, Error> {
    if bound.is_zero() {
        return self.assign_fixed(layouter, F::ZERO);
    }

    // compute largest k such that 2^k <= bound
    let k = (bound.bits() - 1) as usize;
    if *bound == BigUint::from(1u8) << k {
        return self.core_decomposition_chip.assign_less_than_pow2(layouter, value, k);
    }
    let x = self.assign(layouter, value)?;
    self.assert_lower_than_fixed(layouter, &x, bound)?;
    Ok(x)
}

fn assert_lower_than_fixed(
    &self,
    layouter: &mut impl Layouter<F>,
    x: &AssignedNative<F>,
    bound: &BigUint,
) -> Result<(), Error> {
    if let Some(current_bound) = self.constrained_cells.borrow().get(x) {
        if current_bound <= bound {
            return Ok(());
        }
    }
    self.update_bound(x, bound.clone());

    // compute largest k such that 2^k <= bound
    let k = (bound.bits() - 1) as usize;
    let two_pow_k = BigUint::from(1u8) << k; // 2^k

    // if the bound is a power of 2, the check is easier
    if two_pow_k == *bound {
        return self.core_decomposition_chip.assert_less_than_pow2(layouter, x, k);
    }

